const norm=(v:any)=>String(v??"").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]/g,"");
export function historicalPriorReports(year:number,position:"QB"|"RB"|"WR"|"TE"){return DATA[year]?.[position]||[]}
export function findHistoricalPriorReport(year:number,position:"QB"|"RB"|"WR"|"TE",name:string){const key=norm(name);return historicalPriorReports(year,position).find(x=>norm(x.name)===key)||null}
